<?php
if(!defined('UNIOR_INICIADO')){http_response_code(403);exit;}
auth(true);
require_once __DIR__.'/graficos_reportes.php';
$evento=(int)($_GET['event_id']??0);$carrera=trim((string)($_GET['carrera']??''));$desde=trim((string)($_GET['desde']??''));$hasta=trim((string)($_GET['hasta']??''));
$where=['1=1'];$args=[];
if($evento){$where[]='r.event_id=?';$args[]=$evento;}if($carrera!==''){$where[]='r.carrera=?';$args[]=$carrera;}
foreach(['desde'=>'>=','hasta'=>'<='] as $campo=>$op){$valor=$$campo;if($valor!==''){$f=DateTime::createFromFormat('!Y-m-d',$valor);if(!$f||$f->format('Y-m-d')!==$valor){http_response_code(400);exit('Fecha no válida.');}$where[]='r.created_at'.$op.'?';$args[]=$valor.($campo==='desde'?' 00:00:00':' 23:59:59');}}
if($desde!==''&&$hasta!==''&&$desde>$hasta){http_response_code(400);exit('Revise el orden de las fechas.');}
$tipos=['Estudiante'=>'n_estudiante','Profesional'=>'n_profesional','Estudiante BTH'=>'n_bth','UNIOR'=>'n_unior'];
$columnas=[];foreach($tipos as $tipo=>$alias)$columnas[]="COALESCE(SUM(CASE WHEN r.status<>'Anulado' AND r.category='".$tipo."' THEN 1 ELSE 0 END),0) ".$alias;
$activa="r.status<>'Anulado'";$monetaria="$activa AND COALESCE(r.payment_method,'')<>'Descuento por planilla'";
$economia="COALESCE(SUM(CASE WHEN $monetaria THEN r.price ELSE 0 END),0) tarifa_reporte,COALESCE(SUM(CASE WHEN $monetaria THEN r.monto_cobrado ELSE 0 END),0) cobrado_reporte,COALESCE(SUM(CASE WHEN $monetaria THEN GREATEST(0,r.price-r.monto_cobrado) ELSE 0 END),0) saldo_reporte";
$carreraSql="COALESCE(NULLIF(TRIM(r.carrera),''),'Sin carrera')";
$base=' FROM registrations r JOIN events e ON e.id=r.event_id WHERE '.implode(' AND ',$where);
$filas=all("SELECT $carreraSql carrera_resumen,".implode(',',$columnas).",COALESCE(SUM(CASE WHEN $activa THEN 1 ELSE 0 END),0) total_carrera,COALESCE(SUM(CASE WHEN r.status='Anulado' THEN 1 ELSE 0 END),0) anulados_carrera,$economia".$base." GROUP BY $carreraSql ORDER BY carrera_resumen",$args);
$detalle=all("SELECT $carreraSql carrera_resumen,r.category tipo_resumen,COALESCE(SUM(CASE WHEN $activa THEN 1 ELSE 0 END),0) total_carrera,COALESCE(SUM(CASE WHEN r.status='Anulado' THEN 1 ELSE 0 END),0) anulados_carrera,$economia".$base." GROUP BY $carreraSql,r.category ORDER BY carrera_resumen,r.category",$args);
$campos=array_merge(array_values($tipos),['total_carrera','anulados_carrera','tarifa_reporte','cobrado_reporte','saldo_reporte']);$tot=array_fill_keys($campos,0);
foreach($filas as $fila)foreach($campos as $campo)$tot[$campo]+=(float)$fila[$campo];
$head=array_merge(['Carrera'],array_keys($tipos),['Total inscritos','Anulados','Importe Bs','Pagado Bs','Saldo Bs']);
$valores=fn($r)=>array_merge([$r['carrera_resumen']],array_map(fn($k)=>$r[$k],$campos));
if(($_GET['exportar']??'')==='csv'){
 header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="tipos_por_carrera.csv"');$f=fopen('php://output','w');fwrite($f,"\xEF\xBB\xBF");
 $csv=function(array $v)use($f){fputcsv($f,array_map(fn($x)=>preg_match('/^[\s]*[=+@-]/u',(string)$x)?"'".$x:$x,$v),';');};
 $csv($head);foreach($filas as $fila)$csv($valores($fila));$csv(array_merge(['TOTAL'],array_values($tot)));
 $csv([]);$csv(['DETALLE DE MONTOS POR TIPO Y CARRERA']);$csv(['Carrera','Tipo','Inscritos','Anulados','Importe Bs','Pagado Bs','Saldo Bs']);foreach($detalle as $d)$csv([$d['carrera_resumen'],$d['tipo_resumen'],$d['total_carrera'],$d['anulados_carrera'],$d['tarifa_reporte'],$d['cobrado_reporte'],$d['saldo_reporte']]);fclose($f);exit;
}
headerPage('Tipos de participante por carrera');
?>
<style>.tipos-carrera th{vertical-align:middle;background:#8e1828;color:white}.tipos-carrera td:not(:first-child){text-align:right}.tipos-carrera tfoot th{background:#f6e9ec;color:#3d252b}.tortas-reportes{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-top:20px}.torta-reporte{border:1px solid #eadde0;padding:16px;border-radius:9px}.torta-reporte h4{font-size:17px}.torta-contenido{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.torta-contenido svg{width:190px;max-width:100%;height:auto}.leyenda-torta{padding:0;list-style:none;flex:1;font-size:12px;min-width:150px}.leyenda-torta li{display:flex;gap:6px;margin:7px 0}.color-torta{display:inline-block;width:12px;height:12px;flex-shrink:0;margin-top:3px}.detalle-tipos summary{cursor:pointer;font-weight:bold;color:#8e1828;padding:12px 0}@media(max-width:767px){.tortas-reportes{grid-template-columns:1fr}}@media print{.tipos-carrera{font-size:8pt}.tipos-carrera td,.tipos-carrera th{padding:2mm 1mm!important}.torta-reporte{break-inside:avoid}.color-torta{-webkit-print-color-adjust:exact;print-color-adjust:exact}.detalle-tipos:not([open]){display:none}}</style>
<div class="card p-4 no-print"><form method="get"><input type="hidden" name="p" value="reporte_tipos_carrera"><div class="row"><div class="col-md-4"><?php selectField('event_id','Evento',[0=>'Todos']+array_column(all('SELECT id,name FROM events ORDER BY starts_at DESC'),'name','id'),(string)$evento);?></div><div class="col-md-4"><?php selectField('carrera','Carrera',[''=>'Todas']+carrerasInscripcion(),$carrera);?></div><div class="col-md-2"><?php field('desde','Desde',$desde,'date',false);?></div><div class="col-md-2"><?php field('hasta','Hasta',$hasta,'date',false);?></div></div><button class="btn btn-primary">Generar reporte</button> <button class="btn btn-success" name="exportar" value="csv">Exportar Excel (CSV)</button> <button type="button" class="btn btn-outline-primary" onclick="print()">Imprimir / PDF</button></form></div>
<div class="card p-4"><h3>UNIOR · Tipos de participante por carrera</h3><p><b>Inscritos: <?=e((int)$tot['total_carrera'])?></b> · Anulados: <?=e((int)$tot['anulados_carrera'])?> · Pagado: <?=money($tot['cobrado_reporte'])?> · Saldo: <?=money($tot['saldo_reporte'])?></p><p>Cada persona cuenta una sola vez, en su carrera y tipo de participante. Incluye presenciales, en línea e integrantes de grupos. Los anulados se muestran aparte; por planilla solo suma personas, no dinero.</p>
<div class="table-responsive"><table class="table table-bordered table-striped tipos-carrera"><thead><tr><?php foreach($head as $h):?><th scope="col"><?=e($h)?></th><?php endforeach?></tr></thead><tbody><?php foreach($filas as $fila):?><tr><?php foreach($valores($fila) as $i=>$v):?><td><?=$i>=7?money($v):e($v)?></td><?php endforeach?></tr><?php endforeach?><?php if(!$filas):?><tr><td colspan="10">No hay inscripciones para estos filtros.</td></tr><?php endif?></tbody><tfoot><tr><th>TOTAL</th><?php foreach($campos as $i=>$campo):?><th><?=$i>=6?money($tot[$campo]):e((int)$tot[$campo])?></th><?php endforeach?></tr></tfoot></table></div>
<details class="detalle-tipos"><summary>Ver montos por tipo y carrera</summary><div class="table-responsive"><table class="table table-bordered"><thead><tr><th>Carrera</th><th>Tipo</th><th>Inscritos</th><th>Anulados</th><th>Importe Bs</th><th>Pagado Bs</th><th>Saldo Bs</th></tr></thead><tbody><?php foreach($detalle as $d):?><tr><td><?=e($d['carrera_resumen'])?></td><td><?=e($d['tipo_resumen'])?></td><td><?=e($d['total_carrera'])?></td><td><?=e($d['anulados_carrera'])?></td><td><?=money($d['tarifa_reporte'])?></td><td><?=money($d['cobrado_reporte'])?></td><td><?=money($d['saldo_reporte'])?></td></tr><?php endforeach?></tbody></table></div></details>
<div class="tortas-reportes"><?php tortaReporte($filas,'total_carrera','Inscritos por carrera');tortaReporte($filas,'cobrado_reporte','Dinero pagado por carrera',true);?></div></div>
<?php footerPage();
